from pathlib import Path
import argparse
import os
import subprocess as sp
import tempfile

root=Path.cwd()
p=argparse.ArgumentParser()
p.add_argument('snapshot',type=Path)
p.add_argument('--transpose-a',action='store_true')
p.add_argument('--threads',type=int,choices=(16,64),default=64)
args=p.parse_args()
snapshot=args.snapshot.resolve(strict=True)
source=(root/'tests/shared_grid32_test.c').read_text()



source=source.replace('    transpose_a = deep == 2;', '    (void)deep;\n    transpose_a = '+str(int(args.transpose_a))+';')
start=source.index('    void *s =')
end=source.index('    void *r = dlsym(',start)
source=source[:start]+'    void *s = dlsym(library,"framework_blas_stats");\n'+source[end:]
start=source.index('    if (transpose_a) {',source.index('memcpy(&gemm,'))
end=source.index('    memcpy(&reset,',start)
source=source[:start]+'''    memcpy(&route_stats,&s,sizeof(route_stats));
    counter=rectangular_counter;
'''+source[end:]
start=source.index('    if (transpose_a) {',source.index('memcpy(&reset,'))
end=source.index('\nint main(',start)
shapes='{{512,512,256},{528,528,260},{1024,1024,256},{1032,1032,258}}' if args.transpose_a else '{{4096,512,2048},{1056,264,1030},{1040,256,2050}}'
source=source[:start]+'    const int shapes[][3]='+shapes+''';
    int failures=0;
    for(size_t i=0;i<sizeof(shapes)/sizeof(shapes[0]);++i)
        for(int trial=0;trial<2;++trial)
            failures+=check(gemm,counter,reset,shapes[i][0],shapes[i][1],shapes[i][2],0,1,trial);
    dlclose(library);
    if(failures)return 1;
    puts("Complete deep FP32 Strassen scalar-oracle products passed with route, tails, changed inputs and padding");
    return 0;
}
'''+source[end:]
cpus=sorted(os.sched_getaffinity(0))
assert len(cpus)>=args.threads
os.sched_setaffinity(0,cpus[:args.threads])
env=dict(os.environ,CAMBLAS_FRAMEWORK_THREADS=str(args.threads),OMP_NUM_THREADS=str(args.threads),
         OPENBLAS_NUM_THREADS=str(args.threads),OMP_DYNAMIC='FALSE')
with tempfile.TemporaryDirectory(prefix='square32-strassen-',dir=root/'build') as temporary:
    temporary=Path(temporary)
    (temporary/'oracle.c').write_text(source)
    sp.run(['gcc-14','-O2','-std=gnu11','-Wall','-Wextra','-Werror','-fopenmp',
            str(temporary/'oracle.c'),'-ldl','-lm','-o',str(temporary/'oracle')],
           env=env,check=True,timeout=120)
    sp.run([str(temporary/'oracle'),str(snapshot/'libframework_blas.so')],
           env=env,check=True,timeout=300)
